{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "It defines \"early warning signs\" as evidence of a student's safety, health, or behavior problems. Examples include bullying, harassment, or cyberbullying (as a victim or participant), threats of violence, substance abuse, mental health issues, self-harm, and suicidal thoughts. The list is not limited to these examples.",
      "rationale": "Conveys the broad definition and most examples, but omits intimidation and does not expressly convey that receiving threats, as well as making them, is included."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Each local education agency (LEA) and public charter school would have to set up a computer-based system. Teachers and school staff would be required to use it to enter data on early warning signs shown by their students.",
      "rationale": "Identifies both responsible entities, the required system, and mandatory staff entry of enrolled students' early-warning-sign data."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Each LEA and charter school would also have to train every teacher and staff member to spot early warning signs and to enter data into the system.",
      "rationale": "Includes universal teacher and staff training on both identification and data entry."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The system would have to line up with section 49-6-4503, the School Discipline Act, and the school safety plans adopted under the SAVE Act.",
      "rationale": "Conveys all three required sources of alignment; the omitted compilation citations are nonessential."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "It would need a database that can receive and keep the entered student data.",
      "rationale": "Conveys the database's required receipt and retention capabilities, with the staff-entered early-warning data identified in the preceding context."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "It would also have to immediately notify the members of the school's threat assessment team whenever an early warning sign is entered for a student.",
      "rationale": "Conveys the notification trigger, immediacy, and threat-assessment-team recipients within the LEA and charter-school system described."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Those personnel would have to review the notice and any earlier notices for that student. They would then decide whether more action is needed to address the student's behavior.",
      "rationale": "Includes review of current and prior notifications and the determination whether further action is needed."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Each LEA and charter school would send the Department of Education an annual report. It would summarize the data collected in the prior school year and any interventions provided.",
      "rationale": "Identifies the reporting entities, recipient, annual frequency, preceding-school-year data, and interventions."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "Reports would have to follow FERPA, section 10-7-504, the Data Accessibility, Transparency, and Accountability Act, and other relevant privacy laws.",
      "rationale": "Includes each specified privacy authority and the broader requirement to follow other relevant privacy laws."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "If the commissioner of education finds an LEA or charter school is not complying, the commissioner may withhold state funds, in an amount the commissioner decides, until it complies.",
      "rationale": "Conveys the noncompliance finding, discretionary withholding, commissioner-determined amount, and compliance-based endpoint."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "The bill also amends sections 49-6-2701 and 49-6-2702(b) by adding public charter schools, and their governing bodies or directors where the text names boards or directors of schools, alongside LEAs.",
      "rationale": "Identifies the amended section and conveys extension to public charter schools, including corresponding governing-body and director references, without needing to reproduce each textual insertion."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "The bill also amends sections 49-6-2701 and 49-6-2702(b) by adding public charter schools, and their governing bodies or directors where the text names boards or directors of schools, alongside LEAs.",
      "rationale": "Identifies section 49-6-2702(b) and conveys the addition of public charter schools alongside LEA references."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025.",
      "rationale": "States the exact effective date."
    }
  ]
}
